#!/usr/bin/env python3
"""Pure SLDBench scaling-law discovery benchmark."""

import argparse
import json
import os
import random
from dataclasses import dataclass
from pathlib import Path

import numpy as np
from scipy.optimize import least_squares


DATA_DIR = Path(os.environ.get("SCALING_LAW_DATA_DIR", "/data/scaling_law"))
EPS = 1e-8


@dataclass
class BenchmarkData:
    name: str
    X_num_train: np.ndarray
    X_cat_train: np.ndarray
    y_train: np.ndarray
    X_num_test: np.ndarray
    X_cat_test: np.ndarray
    y_test: np.ndarray
    numeric_names: list[str]
    categorical_names: list[str]
    target_name: str


def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)


def load_jsonl(path: Path) -> list[dict]:
    rows = []
    with path.open() as f:
        for line in f:
            line = line.strip()
            if line:
                rows.append(json.loads(line))
    return rows


def pick(mapping: dict, keys: list[str], default=None):
    for key in keys:
        if key in mapping and mapping[key] is not None:
            return mapping[key]
    return default


def safe_float(value, default=np.nan) -> float:
    if value is None:
        return default
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _build_sld_vocab() -> BenchmarkData:
    train_rows = load_jsonl(DATA_DIR / "sldbench__vocab_scaling_law__train.jsonl")
    test_rows = load_jsonl(DATA_DIR / "sldbench__vocab_scaling_law__test.jsonl")

    def convert(rows: list[dict]):
        X_num, X_cat, y = [], [], []
        for row in rows:
            X_num.append([
                safe_float(pick(row, ["non_vocab_parameters", "N"])),
                safe_float(pick(row, ["vocab_size", "V"])),
                safe_float(pick(row, ["num_characters", "D"])),
            ])
            X_cat.append([str(pick(row, ["group"], "all_data"))])
            y.append(safe_float(pick(row, ["unigram_normalized_loss", "loss"])))
        return np.asarray(X_num, dtype=float), np.asarray(X_cat, dtype=object), np.asarray(y, dtype=float)

    X_num_train, X_cat_train, y_train = convert(train_rows)
    X_num_test, X_cat_test, y_test = convert(test_rows)
    return BenchmarkData(
        name="sld-vocab",
        X_num_train=X_num_train,
        X_cat_train=X_cat_train,
        y_train=y_train,
        X_num_test=X_num_test,
        X_cat_test=X_cat_test,
        y_test=y_test,
        numeric_names=["non_vocab_parameters", "vocab_size", "num_characters"],
        categorical_names=["group"],
        target_name="unigram_normalized_loss",
    )


def _build_sld_lrbsz() -> BenchmarkData:
    train_rows = load_jsonl(DATA_DIR / "sldbench__lr_bsz_scaling_law__train.jsonl")
    test_rows = load_jsonl(DATA_DIR / "sldbench__lr_bsz_scaling_law__test.jsonl")

    def convert(rows: list[dict]):
        X_num, X_cat, y = [], [], []
        for row in rows:
            X_num.append([
                safe_float(pick(row, ["lr"])),
                safe_float(pick(row, ["bsz"])),
                safe_float(pick(row, ["data_size", "D"])),
                safe_float(pick(row, ["non_embedding_param_size", "N"])),
            ])
            X_cat.append([str(pick(row, ["group"], "all_data"))])
            y.append(safe_float(pick(row, ["lm_loss", "loss"])))
        return np.asarray(X_num, dtype=float), np.asarray(X_cat, dtype=object), np.asarray(y, dtype=float)

    X_num_train, X_cat_train, y_train = convert(train_rows)
    X_num_test, X_cat_test, y_test = convert(test_rows)
    return BenchmarkData(
        name="sld-lrbsz",
        X_num_train=X_num_train,
        X_cat_train=X_cat_train,
        y_train=y_train,
        X_num_test=X_num_test,
        X_cat_test=X_cat_test,
        y_test=y_test,
        numeric_names=["lr", "bsz", "data_size", "non_embedding_param_size"],
        categorical_names=["group"],
        target_name="lm_loss",
    )


def _build_sld_dataconstrained() -> BenchmarkData:
    train_rows = load_jsonl(DATA_DIR / "sldbench__data_constrained_scaling_law__train.jsonl")
    test_rows = load_jsonl(DATA_DIR / "sldbench__data_constrained_scaling_law__test.jsonl")

    def convert(rows: list[dict]):
        X_num, X_cat, y = [], [], []
        for row in rows:
            X_num.append([
                safe_float(pick(row, ["unique_tokens", "U"])),
                safe_float(pick(row, ["params", "N"])),
                safe_float(pick(row, ["tokens", "D"])),
            ])
            X_cat.append([str(pick(row, ["group"], "all_data"))])
            y.append(safe_float(pick(row, ["loss"])))
        return np.asarray(X_num, dtype=float), np.asarray(X_cat, dtype=object), np.asarray(y, dtype=float)

    X_num_train, X_cat_train, y_train = convert(train_rows)
    X_num_test, X_cat_test, y_test = convert(test_rows)
    return BenchmarkData(
        name="sld-dataconstrained",
        X_num_train=X_num_train,
        X_cat_train=X_cat_train,
        y_train=y_train,
        X_num_test=X_num_test,
        X_cat_test=X_cat_test,
        y_test=y_test,
        numeric_names=["unique_tokens", "params", "tokens"],
        categorical_names=["group"],
        target_name="loss",
    )


def load_benchmark(name: str) -> BenchmarkData:
    if name == "sld-vocab":
        return _build_sld_vocab()
    if name == "sld-lrbsz":
        return _build_sld_lrbsz()
    if name == "sld-dataconstrained":
        return _build_sld_dataconstrained()
    raise ValueError(f"Unknown benchmark: {name}")


def group_labels(X_cat: np.ndarray) -> np.ndarray:
    X_cat = np.asarray(X_cat, dtype=object)
    if X_cat.ndim == 1:
        X_cat = X_cat[:, None]
    if X_cat.size == 0 or X_cat.shape[1] == 0:
        return np.asarray(["__all__"] * len(X_cat), dtype=object)
    return np.asarray(
        [str(v) if v is not None else "__MISSING__" for v in X_cat[:, 0]],
        dtype=object,
    )


def _safe_log_residuals(pred, y):
    pred = np.clip(np.asarray(pred, dtype=float), EPS, None)
    y = np.clip(np.asarray(y, dtype=float), EPS, None)
    return np.log(pred) - np.log(y)


def _linear_residuals(pred, y):
    return np.asarray(pred, dtype=float) - np.asarray(y, dtype=float)


def _fit_generic(X, y, init_u, unpack_fn, predict_fn, n_restarts=6,
                 use_log=True):
    init_u = np.asarray(init_u, dtype=float)
    y = np.asarray(y, dtype=float)
    rng = np.random.default_rng(np.random.randint(0, 2**32 - 1))
    candidates = [init_u]
    for scale in np.linspace(0.05, 0.45, max(n_restarts - 1, 0)):
        candidates.append(init_u + rng.normal(scale=scale, size=init_u.shape))
    best_u, best_score = init_u, float("inf")
    for u0 in candidates:
        def residuals(u):
            try:
                pred = predict_fn(X, unpack_fn(u))
                resid = (_safe_log_residuals(pred, y) if use_log
                         else _linear_residuals(pred, y))
                return np.nan_to_num(resid, nan=1e3, posinf=1e3, neginf=-1e3)
            except Exception:
                return np.full_like(y, 1e3, dtype=float)
        try:
            result = least_squares(residuals, u0, method="trf",
                                   loss="soft_l1", f_scale=0.05, max_nfev=5000)
            u_opt = result.x
        except Exception:
            u_opt = np.asarray(u0, dtype=float)
        pred = predict_fn(X, unpack_fn(u_opt))
        if use_log:
            score = float(np.mean(_safe_log_residuals(pred, y) ** 2))
        else:
            score = float(np.mean((np.asarray(pred, dtype=float) - y) ** 2))
        if np.isfinite(score) and score < best_score:
            best_score, best_u = score, u_opt
    return unpack_fn(best_u)


# -------- sld-vocab: multiplicative interaction on log scales --------

def _vocab_sldagent_predict(X, params):
    n = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
    v = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    E, A, a1, a2, a3, A_vd, g1, g2 = params
    # Cross term links vocab and data.
    cross = A_vd * np.power(v, -g1) * np.power(d, -g2)
    return E + A * np.power(n, -a1) * np.power(v, -a2) * np.power(d, -a3) + cross


def _fit_vocab_sldagent(X, y):
    y = np.asarray(y, dtype=float)
    def unpack(u):
        E = u[0]
        A = np.exp(u[1])
        a1, a2, a3 = np.exp(u[2]), np.exp(u[3]), np.exp(u[4])
        A_vd = np.exp(u[5])
        g1, g2 = np.exp(u[6]), np.exp(u[7])
        return np.array([E, A, a1, a2, a3, A_vd, g1, g2], dtype=float)
    init = np.array([
        float(np.median(y)),
        np.log(max(abs(np.std(y)), 0.1)),
        np.log(0.1), np.log(0.2), np.log(0.2),
        np.log(max(abs(np.std(y)), 0.05)),
        np.log(0.3), np.log(0.3),
    ])
    return _fit_generic(X, y, init, unpack, _vocab_sldagent_predict,
                        n_restarts=8, use_log=False)


# -------- sld-lrbsz: Chinchilla base + joint (lr, bsz) coupling --------

def _lrbsz_sldagent_predict(X, params):
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-8, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 3], dtype=float), 1.0, None)
    E, A, alpha, B, beta, k, log_lr_star, log_bsz_star, rho = params
    base = E + A * np.power(n, -alpha) + B * np.power(d, -beta)
    dx = np.log(lr) - log_lr_star
    dy = np.log(bsz) - log_bsz_star
    # Correlated quadratic bowl around (lr*, bsz*) with coupling rho.
    penalty = k * (dx * dx + dy * dy + 2.0 * rho * dx * dy)
    return base + penalty


def _fit_lrbsz_sldagent(X, y):
    y = np.asarray(y, dtype=float)
    lr = np.clip(np.asarray(X[:, 0], dtype=float), 1e-8, None)
    bsz = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    def unpack(u):
        E = u[0]
        A = np.exp(u[1]); alpha = np.exp(u[2])
        B = np.exp(u[3]); beta = np.exp(u[4])
        k = np.exp(u[5])
        log_lr_star = u[6]; log_bsz_star = u[7]
        rho = np.tanh(u[8])  # keep in (-1, 1)
        return np.array([E, A, alpha, B, beta, k,
                         log_lr_star, log_bsz_star, rho], dtype=float)
    init = np.array([
        float(max(y.min() * 0.9, 0.1)),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.3),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.3),
        np.log(0.05),
        float(np.log(np.median(lr))), float(np.log(np.median(bsz))),
        0.0,
    ])
    return _fit_generic(X, y, init, unpack, _lrbsz_sldagent_predict,
                        n_restarts=10, use_log=True)


# -------- sld-dataconstrained: multiplicative repeat-efficiency term ---

def _dconstrained_sldagent_predict(X, params):
    u = np.clip(np.asarray(X[:, 0], dtype=float), 1.0, None)
    n = np.clip(np.asarray(X[:, 1], dtype=float), 1.0, None)
    d = np.clip(np.asarray(X[:, 2], dtype=float), 1.0, None)
    E, A, alpha, B, beta, R = params
    ratio = np.clip(d / u, 0.0, 200.0)
    # Repeat-efficiency: multiplier decays smoothly with repetition.
    efficiency = 1.0 / (1.0 + ratio / np.maximum(R, 1e-3))
    d_eff = np.maximum(d * efficiency, 1.0)
    return E + A * np.power(n, -alpha) + B * np.power(d_eff, -beta)


def _fit_dconstrained_sldagent(X, y):
    y = np.asarray(y, dtype=float)
    def unpack(u):
        E = np.exp(u[0])
        A = np.exp(u[1]); alpha = np.exp(u[2])
        B = np.exp(u[3]); beta = np.exp(u[4])
        R = np.exp(u[5])
        return np.array([E, A, alpha, B, beta, R], dtype=float)
    init = np.array([
        np.log(max(y.min() * 0.9, 0.1)),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.35),
        np.log(max(y.max() - y.min(), 0.1)), np.log(0.35),
        np.log(5.0),
    ])
    return _fit_generic(X, y, init, unpack, _dconstrained_sldagent_predict,
                        n_restarts=8, use_log=True)


def _sldagent_fit_params(benchmark_name, X, y):
    if benchmark_name == "sld-vocab":
        return _fit_vocab_sldagent(X, y)
    if benchmark_name == "sld-lrbsz":
        return _fit_lrbsz_sldagent(X, y)
    if benchmark_name == "sld-dataconstrained":
        return _fit_dconstrained_sldagent(X, y)
    raise ValueError(f"Unsupported benchmark: {benchmark_name}")


def _sldagent_predict_params(benchmark_name, X, params):
    if benchmark_name == "sld-vocab":
        return _vocab_sldagent_predict(X, params)
    if benchmark_name == "sld-lrbsz":
        return _lrbsz_sldagent_predict(X, params)
    if benchmark_name == "sld-dataconstrained":
        return _dconstrained_sldagent_predict(X, params)
    raise ValueError(f"Unsupported benchmark: {benchmark_name}")


class ScalingLawModel:
    """SLDAgent-style symbolic baseline for the harder SLDBench subsets.

    Uses discovered-style symbolic forms with cross-axis interactions:
    - vocab: additive power law with extra V*D cross term
    - lrbsz: Chinchilla base + correlated (lr, bsz) quadratic bowl
    - dataconstrained: multiplicative repeat-efficiency factor on D_eff
    """

    def __init__(self, benchmark_name, numeric_names=None, categorical_names=None):
        self.benchmark_name = benchmark_name
        self.numeric_names = list(numeric_names or [])
        self.categorical_names = list(categorical_names or [])
        self.group_params_ = {}
        self.default_params_ = None

    def fit(self, X_num, X_cat, y):
        X_num = np.asarray(X_num, dtype=float)
        y = np.asarray(y, dtype=float)
        labels = group_labels(X_cat)
        fitted = []
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = _sldagent_fit_params(self.benchmark_name,
                                          X_num[mask], y[mask])
            self.group_params_[group] = params
            fitted.append(params)
        self.default_params_ = np.median(np.stack(fitted, axis=0), axis=0)
        return self

    def predict(self, X_num, X_cat):
        X_num = np.asarray(X_num, dtype=float)
        labels = group_labels(X_cat)
        preds = np.zeros(len(labels), dtype=float)
        for group in sorted(set(labels.tolist())):
            mask = labels == group
            params = self.group_params_.get(group, self.default_params_)
            preds[mask] = _sldagent_predict_params(self.benchmark_name,
                                                   X_num[mask], params)
        return preds


# ============================================================
# Evaluation
# ============================================================

def r2_score(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    y_true = np.asarray(y_true, dtype=float)
    y_pred = np.asarray(y_pred, dtype=float)
    denom = np.sum((y_true - y_true.mean()) ** 2)
    if denom < EPS:
        return 0.0
    return float(1.0 - np.sum((y_true - y_pred) ** 2) / denom)


def mean_absolute_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    return float(np.mean(np.abs(np.asarray(y_true, dtype=float) - np.asarray(y_pred, dtype=float))))


def mean_squared_error(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    diff = np.asarray(y_true, dtype=float) - np.asarray(y_pred, dtype=float)
    return float(np.mean(diff ** 2))


def run_benchmark(benchmark: str, seed: int, output_dir: str) -> None:
    set_seed(seed)
    data = load_benchmark(benchmark)
    model = ScalingLawModel(data.name, data.numeric_names, data.categorical_names)
    model.fit(data.X_num_train, data.X_cat_train, data.y_train)

    train_pred = model.predict(data.X_num_train, data.X_cat_train)
    test_pred = model.predict(data.X_num_test, data.X_cat_test)

    train_r2 = r2_score(data.y_train, train_pred)
    train_mae = mean_absolute_error(data.y_train, train_pred)

    n_test = len(data.X_num_test)
    test_pred = np.asarray(test_pred, dtype=float).reshape(-1)
    if test_pred.shape[0] != n_test:
        print(
            f"ERROR: predict() returned {test_pred.shape[0]} predictions "
            f"for {n_test} test rows.",
            flush=True,
        )
        raise SystemExit(1)

    n_features = int(getattr(model, "num_features_", data.X_num_train.shape[1]))
    print(
        "TRAIN_METRICS "
        f"n_train={len(data.y_train)} n_test={n_test} "
        f"n_features={n_features} train_r2={train_r2:.6f} train_mae={train_mae:.6f}",
        flush=True,
    )
    # The held-out test targets never enter this process (the baked test
    # JSONLs carry features only).  This process reports nothing that is
    # scored: it writes its test predictions to <output_dir>/<benchmark>_predictions.json,
    # and the fixed run script (a separate, trusted process that starts after
    # this one has exited) validates that file and hands the predictions to the
    # scorer, which joins them against the held-out targets.
    output_path = Path(output_dir)
    output_path.mkdir(parents=True, exist_ok=True)
    pred_file = output_path / f"{benchmark}_predictions.json"
    with pred_file.open("w") as f:
        json.dump(
            {
                "benchmark": benchmark,
                "target": data.target_name,
                "y_pred": [float(v) for v in test_pred],
            },
            f,
            indent=2,
        )
    print(f"PRED_FILE benchmark={benchmark} n={n_test} path={pred_file}", flush=True)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--benchmark", required=True)
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--output-dir", default="./output")
    args = parser.parse_args()
    run_benchmark(args.benchmark, args.seed, args.output_dir)


if __name__ == "__main__":
    main()
